const D = { scale:1, density:.5, energy:.6, speed:1, hue:130, x:.5, y:.5, fade:.5, scan:.5, style:'terminal', act:'drift', seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const clp=(v,a,b)=>Math.max(a,Math.min(b,v));
const md=(a,n)=>((a%n)+n)%n;
const lrp=(a,b,t)=>a+(b-a)*t;
const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453;return s-Math.floor(s);};

const W=width,Hh=height,u=Math.min(W,Hh);
const H=md(P.hue,360);
const style=P.style;
const term=style==='terminal', lich=style==='lichen', ice=style==='ice', asc=style==='ascii';
const en=clp(P.energy,0,1);

// t0 / beat reset guard
if(S.lastBeat==null||K.beat<S.lastBeat)S.lastBeat=K.beat;

// ---- grid geometry (cap total cells ~2600) ----
let cellPx=Math.max(u*0.020*clp(P.scale,0.5,2.5), Math.sqrt(W*Hh/2600));
const cols=Math.max(6,Math.floor(W/cellPx));
const rows=Math.max(6,Math.floor(Hh/cellPx));
const cw=W/cols, ch=Hh/rows;

// ---- rule table (era changes per section) ----
const RULES=[
  {b:[3],s:[2,3]},        // Conway Life
  {b:[3,6],s:[2,3]},      // HighLife
  {b:[2],s:[]},           // Seeds (explosive)
  {b:[3,4],s:[3,4]},      // 34 Life
  {b:[3,6,7,8],s:[3,4,6,7,8]}, // Day & Night
  {b:[3,5,7],s:[1,3,5,8]},// Amoeba-ish
  {b:[3,6],s:[1,2,5]},    // 2x2-ish
  {b:[1],s:[1]}           // Gnarl (filigree)
];
const ruleIdx=md(K.section+Math.floor(P.seed/7),RULES.length);
const RULE=RULES[ruleIdx];
const bMask=new Uint8Array(9), sMask=new Uint8Array(9);
for(const k of RULE.b)bMask[k]=1; for(const k of RULE.s)sMask[k]=1;

// ---- seeded init / rebuild on size|seed change ----
function seedGrid(fill){
  const g=new Uint8Array(cols*rows);
  const age=new Float32Array(cols*rows);
  for(let i=0;i<cols*rows;i++){ if(fr(i*2.3+7.1)<fill){g[i]=1;age[i]=1;} }
  return {g,age};
}
const gkey=cols+'x'+rows+':'+P.seed;
if(!S.grid || S.gkey!==gkey){
  S.gkey=gkey;
  const o=seedGrid(clp(P.density,0.05,1)*0.42);
  S.grid=o.g; S.age=o.age; S.prev=o.g.slice();
  S.stepBeat=Math.floor(K.beat*P.speed);
}

// ---- CA step (beat-locked, with phase fade between) ----
function neighbors(g,x,y){
  let c=0;
  for(let ox=-1;ox<=1;ox++)for(let oy=-1;oy<=1;oy++){
    if(ox===0&&oy===0)continue;
    const nx=md(x+ox,cols), ny=md(y+oy,rows);
    c+=g[ny*cols+nx];
  }
  return c;
}
function stepCA(){
  const g=S.grid; const ng=new Uint8Array(cols*rows); const age=S.age;
  let live=0;
  for(let y=0;y<rows;y++)for(let x=0;x<cols;x++){
    const idx=y*cols+x; const c=neighbors(g,x,y);
    let v=0;
    if(g[idx]){ v=sMask[c]?1:0; } else { v=bMask[c]?1:0; }
    ng[idx]=v;
    if(v){ age[idx]=g[idx]?Math.min(age[idx]+1,120):1; live++; } else { age[idx]=Math.max(age[idx]-2,0); }
  }
  S.prev=S.grid; S.grid=ng;
  // reseed to prevent death / blackout
  const total=cols*rows;
  const bloom = P.act==='bloom' ? (0.10+0.5*K.intensity) : 0.055;
  if(live<total*bloom){
    const cx=Math.floor(clp(P.x,0,1)*(cols-1)), cy=Math.floor(clp(P.y,0,1)*(rows-1));
    const rad=Math.round(lrp(2,7,clp(P.density,0,1)));
    const jx=Math.floor(fr(K.section*3.7+11)*cols), jy=Math.floor(fr(K.section*3.7+12)*rows);
    for(let dy=-rad;dy<=rad;dy++)for(let dx=-rad;dx<=rad;dx++){
      const rr=fr(dx*7.3+dy*3.1+K.section*5.0);
      if(rr<0.5){
        let px=md(cx+dx,cols), py=md(cy+dy,rows); S.grid[py*cols+px]=1; S.age[py*cols+px]=1;
        px=md(jx+dx,cols); py=md(jy+dy,rows); S.grid[py*cols+px]=1; S.age[py*cols+px]=1;
      }
    }
  }
}
const wantBeat=Math.floor(K.beat*clp(P.speed,0.25,4));
if(S.stepBeat==null||wantBeat<S.stepBeat)S.stepBeat=wantBeat; // reset guard
let steps=0;
while(S.stepBeat<wantBeat && steps<3){ stepCA(); S.stepBeat++; steps++; }
S.lastBeat=K.beat;

// ---- render ----
const g=S.grid, prev=S.prev, age=S.age;
const emerge=clp(K.phase*clp(P.speed,0.25,4),0,1); // 0->1 progress to next step
const fadeK=clp(P.fade,0,1);

// background floor
noStroke();
if(term||asc){ background(H,20,5); }
else if(ice){ background(212,40,9); }
else { background(96,18,14); } // lichen stone

// subtle base glow so never blackout
blendMode(BLEND);

const glow = term ? 0.9 : ice ? 0.85 : 0.7;
const flick = 1 + (term? (Math.sin(K.t*7.0)*0.03 + Math.sin(K.t*31.0)*0.015) : 0);
const pulse = K.pulse*0.4 + A.bass*0.5;

if(asc){
  textAlign(CENTER,CENTER);
  textSize(ch*0.92);
  const gl=['.',':','+','*','#','@'];
  for(let y=0;y<rows;y++)for(let x=0;x<cols;x++){
    const idx=y*cols+x; const a=age[idx];
    if(a<=0 && !g[idx])continue;
    const on=g[idx];
    const born=on&&!prev[idx];
    const dyingA=(!on&&prev[idx])?(1-emerge):1;
    const bornA=born?emerge:1;
    const lvl=clp(a/60,0,1);
    const ch2=gl[Math.min(gl.length-1,Math.floor(lvl*gl.length))];
    const b=clp((on?70:38)*bornA*dyingA*glow*flick+pulse*30,0,100);
    fill(md(H+(a>40?-14:0),360), on?70:40, b, on?100:70);
    text(on?ch2:'.', x*cw+cw*0.5, y*ch+ch*0.52);
  }
} else {
  for(let y=0;y<rows;y++)for(let x=0;x<cols;x++){
    const idx=y*cols+x; const a=age[idx];
    if(a<=0 && !g[idx])continue;
    const on=g[idx];
    const born=on&&!prev[idx];
    const dying=!on&&prev[idx];
    const app=born?emerge:1;
    const disA=dying?(1-emerge)*fadeK:1;
    const lvl=clp(a/70,0,1);
    const px=x*cw, py=y*ch;
    if(term){
      const b=clp((on?lrp(55,95,lvl):30)*app*disA*flick+pulse*40,0,100);
      fill(md(H-lvl*16,360), lrp(85,55,lvl), b, on?100:60*fadeK);
      const m=cw*0.10; rect(px+m,py+m,cw-2*m,ch-2*m);
    } else if(ice){
      const b=clp((on?lrp(60,100,lvl):40)*app*disA+pulse*20,0,100);
      fill(lrp(210,190,lvl), lrp(55,18,lvl), b, on?100:55*fadeK);
      const cxp=px+cw*0.5, cyp=py+ch*0.5, s=cw*0.5*(on?lrp(0.55,0.95,lvl)*app:0.5*disA);
      beginShape(); vertex(cxp,cyp-s); vertex(cxp+s*0.8,cyp); vertex(cxp,cyp+s); vertex(cxp-s*0.8,cyp); endShape(CLOSE);
    } else { // lichen organic
      const b=clp((on?lrp(38,72,lvl):30)*app*disA+pulse*14,0,100);
      const hh=md(H + lrp(18,-26,lvl) + fr(idx*1.7)*10,360);
      fill(hh, lrp(45,68,lvl), b, on?100:50*fadeK);
      const cxp=px+cw*0.5+ (fr(idx*2.1)-0.5)*cw*0.2, cyp=py+ch*0.5+(fr(idx*3.3)-0.5)*ch*0.2;
      const s=cw*(on?lrp(0.30,0.52,lvl)*app:0.34*disA);
      ellipse(cxp,cyp,s*2,s*2*0.92);
    }
  }
}

// ---- phosphor / CRT overlay (real-time motion floor, never re-phases) ----
if(term||asc){
  blendMode(MULTIPLY); noStroke();
  const scanA=clp(P.scan,0,1)*38;
  const roll=md(K.t*u*0.10, ch*2); // continuous vertical roll
  for(let y=-1;y*ch*2 - roll < Hh; y++){
    const yy=y*ch*2 - roll;
    fill(0,0,0,scanA); rect(0,yy,W,ch);
  }
  blendMode(BLEND);
  // moving scan-beam highlight
  blendMode(ADD);
  const beamY=md(K.t*0.09,1)*Hh;
  fill(H,50,100,10+en*10); rect(0,beamY-ch,W,ch*2);
  // blinking cursor
  if(Math.sin(K.t*3.2)>0){ fill(H,60,100,60); rect(md(K.beat*0.7,cols)*cw, (rows-2)*ch, cw*0.8, ch*0.8); }
  blendMode(BLEND);
} else {
  // soft light drift for ice/lichen so motion floor holds even if CA stalls
  blendMode(ADD); noStroke();
  const dx=(0.5+0.5*Math.sin(K.t*0.15))*W, dy=(0.5+0.5*Math.cos(K.t*0.11))*Hh;
  fill(ice?200:70, 30, 100, 6+A.rms*20); ellipse(dx,dy,u*0.5,u*0.5);
  blendMode(BLEND);
}
blendMode(BLEND);
